INSERT INTO `events` (`id`, `title`, `slug`, `event_banner`, `event_mobile_banner`, `event_date`, `event_location`, `event_time`, `content`, `short_description`, `meta_title`, `meta_description`, `schema_code`, `created_at`)
VALUES
	(4,'Childhood Cancer Day','childhood-cancer-day','childhood-cancer-day2_66bebed101e05.jpg','childhood-cancer-day-mobile_66bebed1020d9.jpg','2024-02-13','Bangalore','NA','<p>&nbsp;A joy filled event with the pediatric patients, with some games and cards making activity for they caretakers and doctors with a heart touching message.</p>\r\n<p>At Swasti Gallery, the dual celebrations of Childhood Cancer Day and Valentine\'s Day brought an abundance of love and resilience as pediatric patients came together for a special event. With hearts full of creativity and hope, the children enthusiastically crafted greeting cards and decorated small wooden boards with a kaleidoscope of colorful tapes, stickers, paint, stamps, and whimsical wooden cutouts of flowers, unicorns, and wings. Their artistic endeavors were not only expressions of joy but also reflections of their indomitable spirit in the face of adversity. Amidst shared laughter and the aroma of snacks, the children reveled in a lively photoshoot, capturing precious moments of camaraderie and strength. The celebration was made even more special with the generous donation of a celebration gifts box by Keto, ensuring that each pediatric patient felt cherished and remembered on this memorable occasion. It was a day filled with love, creativity, and unwavering support, highlighting the beauty and resilience of these young warriors in their journey against cancer.</p>','<p>At Swasti Gallery, the dual celebrations of Childhood Cancer Day and Valentine\'s Day brought an abundance of love and resilience as pediatric patients came together for a special event. With hearts full of creativity and hope, the children enthusiastically crafted greeting cards and decorated small wooden boards with a kaleidoscope of colorful tapes, stickers, paint, stamps, and whimsical wooden cutouts of flowers,</p>','Childhood Cancer Day','At Swasti Gallery, the dual celebrations of Childhood Cancer Day and Valentine\'s Day brought an abundance of love and resilience as pediatric patients came together for a special event. With hearts full of creativity and hope, the children enthusiastically crafted greeting cards and decorated small wooden boards with a kaleidoscope of colorful tapes, stickers, paint, stamps, and whimsical wooden cutouts of flowers,','','2024-08-16 08:22:01'),
	(5,'Chirstmas and New Year Celebration','christmas-and-new-year-celebration','new-year-image_66debadac2c91.jpg','new-year-image_66debadac3074.jpg','2024-01-06','Bangalore','NA','<p>At Swasti Gallery, the New Year and Christmas celebrations were nothing short of heartwarming as pediatric patients immersed themselves in festive cheer. These resilient children crafted thoughtful greeting cards, adorned with creativity and love, for their dedicated nurses, doctors, and caretakers, along with some for themselves. A few artistic souls even captured the essence of their caregivers by intricately drawing them with their distinctive props, like red pockets and spectacles, adding a personal touch to their expressions of gratitude. Amidst shared laughter and joy, the children indulged in delicious snacks, enjoyed a lively photo shoot, and received gifts generously donated by Alvarez &amp; Marsal India Private Limited, catering to all age groups. It was a celebration of the holidays and the enduring spirit and camaraderie that binds these young fighters and their caregivers together.</p>','<p>At Swasti Gallery, the New Year and Christmas celebrations were nothing short of heartwarming as pediatric patients immersed themselves in festive cheer. These resilient children crafted thoughtful greeting cards, adorned with creativity and love, for their dedicated nurses, doctors, and caretakers, along with some for themselves.</p>','Chirstmas and New Year Celebration','At Swasti Gallery, the New Year and Christmas celebrations were nothing short of heartwarming as pediatric patients immersed themselves in festive cheer. These resilient children crafted thoughtful greeting cards, adorned with creativity and love, for their dedicated nurses, doctors, and caretakers, along with some for themselves.','','2024-08-16 08:30:41');

